+    font-size: 0.85rem;
+    transition: background 0.15s;
+}
+
+.send-btn:hover:not(:disabled) {
+    background: #3585e0;
+}
+
+.send-btn:disabled {
+    opacity: 0.5;
+    cursor: not-allowed;
+}
+
+/* No Channel Selected */
+.no-channel-selected {
+    flex: 1;
+    display: flex;
+    align-items: center;
+    justify-content: center;
+    color: #999;
+    font-size: 1.1rem;
+}
+
+/* Thread Panel */
+.thread-panel {
+    width: 25%;
+    min-width: 280px;
+    display: flex;
+    flex-direction: column;
+    border-left: 1px solid #e0e0e0;
+    background: #fafbfc;
+}
+
+.thread-header {
+    display: flex;
+    align-items: center;
+    justify-content: space-between;
+    padding: 12px 16px;
+    border-bottom: 1px solid #e0e0e0;
+    background: #fff;
+}
+
+.thread-header h3 {
+    margin: 0;
+    font-size: 1rem;
+}
+
+.close-btn {
+    background: none;
+    border: none;
+    font-size: 1.2rem;
+    cursor: pointer;
+    color: #666;
+    padding: 4px 8px;
+    border-radius: 4px;
+}
+
+.close-btn:hover {
+    background: #eee;
+}
+
+.thread-root-quote {
+    padding: 12px 16px;
+    border-bottom: 1px solid #e0e0e0;
+    background: #f5f7fa;
+    border-left: 3px solid #4a9eff;
+    margin: 12px 16px;
+    border-radius: 4px;
+}
+
+.thread-root-quote .message-author {
+    font-size: 0.85rem;
+}
+
+.thread-root-quote p {
+    margin: 4px 0 0;
+    font-size: 0.85rem;
+    color: #444;
+}
+
+.thread-replies {
+    flex: 1;
+    overflow-y: auto;
+    padding: 8px 16px;
+}
+
+.thread-replies .message-item {
+    padding: 8px 0;
+    border-bottom: 1px solid #f0f0f0;
+}
+
+.thread-replies .message-item:last-child {
+    border-bottom: none;
+}
